#include "gvs_audio_buffer.h"
#include <string.h>
void df_gvs_audio_buffer_init(struct df_gvs_audio_buffer *b){if(b!=NULL)memset(b,0,sizeof(*b));}
void df_gvs_audio_buffer_reset(struct df_gvs_audio_buffer *b,uint64_t generation){if(b==NULL)return;memset(b,0,sizeof(*b));b->generation=generation;}
int df_gvs_audio_buffer_push(struct df_gvs_audio_buffer *b,const uint8_t *data,size_t length,uint16_t sequence,uint64_t generation,uint64_t timestamp_ms){size_t i;if(b==NULL||data==NULL||length==0||length>DF_GVS_AUDIO_BUFFER_CAPACITY)return -1;if(b->generation!=generation)df_gvs_audio_buffer_reset(b,generation);if(b->has_sequence&&(uint16_t)(b->last_sequence+1U)!=sequence)b->sequence_gaps++;for(i=0;i<length;i++){if(b->length==DF_GVS_AUDIO_BUFFER_CAPACITY){b->read_offset=(b->read_offset+1U)%DF_GVS_AUDIO_BUFFER_CAPACITY;b->length--;}b->data[b->write_offset]=data[i];b->write_offset=(b->write_offset+1U)%DF_GVS_AUDIO_BUFFER_CAPACITY;b->length++;}b->last_sequence=sequence;b->has_sequence=true;b->packet_count++;b->byte_count+=length;b->last_timestamp_ms=timestamp_ms;return 0;}
int df_gvs_audio_buffer_read(struct df_gvs_audio_buffer *b,uint8_t *output,size_t capacity,size_t *length){size_t i,count;if(b==NULL||output==NULL||length==NULL)return -1;count=b->length<capacity?b->length:capacity;for(i=0;i<count;i++){output[i]=b->data[b->read_offset];b->read_offset=(b->read_offset+1U)%DF_GVS_AUDIO_BUFFER_CAPACITY;}b->length-=count;*length=count;return 0;}
int df_gvs_audio_buffer_status(const struct df_gvs_audio_buffer *b,struct df_gvs_audio_status *s){if(b==NULL||s==NULL)return -1;s->generation=b->generation;s->packet_count=b->packet_count;s->byte_count=b->byte_count;s->sequence_gaps=b->sequence_gaps;s->last_timestamp_ms=b->last_timestamp_ms;s->buffered_bytes=b->length;s->ready=b->length>0;return 0;}
